g = json.loads(P.read_text())
ids = {t["id"] for t in g}
taken = {a for t in g for a in t["aliases"]}
added = 0
for tid, display, aliases, sense, short, other in T:
    if tid in ids:
        continue
    aliases = [a for a in aliases if a not in taken]  # 既存の用語と別名が重なったら既存を優先
    if not aliases:
        continue
    taken.update(aliases)
    t = {"id": tid, "display": display, "aliases": aliases, "sense": sense, "short": short}
    if other:
        t["other"] = other
    g.append(t); added += 1
P.write_text("[\n" + ",\n".join(" " + json.dumps(t, ensure_ascii=False) for t in g) + "\n]\n")
print(f"added {added}, total {len(g)}")
